message.content:
{
  "description": "A single quadrupedal creature is shown in right-facing profile standing on a small patch of dirt with sparse grass, pebbles and dry leaves. The body is elongated and low to the ground with a pale creamy-white underbelly and wrinkled skin on the sides and limbs, and a darker mottled gray-brown on the back and head. The head is broad, flat and blunt-snouted with large dark eyes and a slightly smiling mouth. Behind the head are feathery external gills. Most of the dorsal surface from the neck to the base of the tail is covered by a dense, overlapping armor of large brown keratinous scales with lighter edges. The tail is long, thick and muscular with a dark fin-like ridge along the top, extending off the left edge of the image. Four stout limbs with clawed toes support the body.",
  "parts": [
    {
      "part": "head",
      "looks_like": "broad, flattened and blunt-snouted with large round dark eyes with light irises on the sides, small nostrils at the tip, a pale cream lower jaw and throat, and mottled gray-brown skin on the top",
      "where": "at the front right end of the body, facing right"
    },
    {
      "part": "gills",
      "looks_like": "six feathery pinkish-red external gill stalks with fine filamentous branches, three on each side of the head behind the eyes, the ones on the near side more fully visible",
      "where": "projecting outward from the sides of the neck just behind the head"
    },
    {
      "part": "legs",
      "looks_like": "four short, thick, fleshy limbs with wrinkled pale skin and visible folds at the joints",
      "where": "two forelegs under the chest and two hindlegs under the rear, supporting the body on the ground"
    },
    {
      "part": "feet",
      "looks_like": "broad feet with five distinct toes each ending in small dark claws, pale with wrinkled skin",
      "where": "at the ends of each leg in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "long, thick at the base and tapering, with a dark continuous fin-like dorsal crest along the top, dark gray-brown above and pale below, with a slightly glossy texture",
      "where": "extending from the rear of the body to the left, cropped by the left edge of the image"
    },
    {
      "part": "scales",
      "looks_like": "large overlapping rounded keratinous scales in shades of dark and medium brown with lighter tan edges and fine radial striations, forming a dense armor",
      "where": "covering most of the dorsal back from behind the gills to the tail base, and as a small isolated patch of about a dozen scales on the outer side of the right hind leg"
    },
    {
      "part": "plates",
      "looks_like": "same overlapping brown armor plates as the scales, thick and scale-like with curved outer margins",
      "where": "forming the continuous dorsal covering over the back"
    },
    {
      "part": "markings",
      "looks_like": "mottled dark gray-brown pigmentation on the dorsal head, back and tail that fades irregularly into creamy white on the sides, belly and limbs, with wrinkled skin folds and a slightly glossy moist appearance",
      "where": "over the entire body, darkest on the back and top of head, palest on the ventral surface"
    }
  ],
  "attached_objects": [],
  "animals": ["axolotl", "pangolin"],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0
}
